mapper.select:
SELECT history.* FROM T_LH_SCHEDULE_RESULT history INNER JOIN ( SELECT SUBSTRING_INDEX( GROUP_CONCAT( CAST(close_out.ID AS CHAR) ORDER BY close_out.closeOutTime DESC, close_out.SCHEDULE_DATE DESC, close_out.ID DESC SEPARATOR ',' ), ',', 1 ) AS selectedId, MAX(close_out.closeOutTime) AS closeOutTime FROM ( SELECT ID, LH_MACHINE_CODE, SCHEDULE_DATE, COALESCE( CASE WHEN CLASS8_IS_END = '1' THEN CLASS8_END_TIME WHEN CLASS7_IS_END = '1' THEN CLASS7_END_TIME WHEN CLASS6_IS_END = '1' THEN CLASS6_END_TIME WHEN CLASS5_IS_END = '1' THEN CLASS5_END_TIME WHEN CLASS4_IS_END = '1' THEN CLASS4_END_TIME WHEN CLASS3_IS_END = '1' THEN CLASS3_END_TIME WHEN CLASS2_IS_END = '1' THEN CLASS2_END_TIME WHEN CLASS1_IS_END = '1' THEN CLASS1_END_TIME END, SPEC_END_TIME, SCHEDULE_DATE ) AS closeOutTime FROM T_LH_SCHEDULE_RESULT WHERE FACTORY_CODE = #{factoryCode} AND SCHEDULE_DATE >= DATE_SUB(#{scheduleDate}, INTERVAL 7 DAY) AND SCHEDULE_DATE < #{scheduleDate} AND LH_MACHINE_CODE IN
#{machineCode}
AND ( CLASS1_IS_END = '1' OR CLASS2_IS_END = '1' OR CLASS3_IS_END = '1' OR CLASS4_IS_END = '1' OR CLASS5_IS_END = '1' OR CLASS6_IS_END = '1' OR CLASS7_IS_END = '1' OR CLASS8_IS_END = '1' ) ) close_out WHERE close_out.closeOutTime < #{closeOutBefore} GROUP BY close_out.LH_MACHINE_CODE ) latest ON history.ID = latest.selectedId

SELECT DISTINCT MATERIAL_CODE FROM T_LH_SCHEDULE_RESULT WHERE FACTORY_CODE = #{factoryCode} AND SCHEDULE_DATE >= #{startDate} AND SCHEDULE_DATE < #{endDate} AND MATERIAL_CODE IN
#{materialCode}
AND ( COALESCE(CLASS1_PLAN_QTY, 0) > 0 OR COALESCE(CLASS2_PLAN_QTY, 0) > 0 OR COALESCE(CLASS3_PLAN_QTY, 0) > 0 OR COALESCE(CLASS4_PLAN_QTY, 0) > 0 OR COALESCE(CLASS5_PLAN_QTY, 0) > 0 OR COALESCE(CLASS6_PLAN_QTY, 0) > 0 OR COALESCE(CLASS7_PLAN_QTY, 0) > 0 OR COALESCE(CLASS8_PLAN_QTY, 0) > 0 )
